def _rocos_get(base_url: str, path: str, params: Optional[dict] = None) -> dict:
    """向 ROCOS API 发送 GET 请求，返回解析后的 JSON 响应"""
    url = f"{base_url.rstrip('/')}{path}"
    if params:
